function foreground(hex){const rgb=hex.slice(1).match(/../g).map(s=>parseInt(s,16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return (.2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2])>.179?'#000000':'#ffffff'}
